import{_ as e,o,c as s,ag as r}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Modeling Strategies","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build-modeling-strategies.md","filePath":"guide/build-modeling-strategies.md"}'),a={name:"guide/build-modeling-strategies.md"};function n(i,t,d,l,c,h){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="modeling-strategies" tabindex="-1">Modeling Strategies <a class="header-anchor" href="#modeling-strategies" aria-label="Permalink to &quot;Modeling Strategies&quot;">​</a></h1><p>Central gives you four ways to model &quot;this record is more complicated than one flat row&quot;: <strong>Extra Primary Keys</strong>, <strong>Built-In lists</strong>, <strong>Custom Lists</strong>, and <strong>Projections</strong>. Three of the four are chosen from the same control — the <strong>List Type</strong> selector on a Data Model&#39;s <strong>Lists</strong> tab — and the fourth lives one tab over.</p><p>They look similar from the outside and behave very differently downstream. This page is about picking the right one.</p><div class="tip custom-block"><p class="custom-block-title">The whole decision in one question</p><p><strong>Is it the same record, or a different record?</strong></p><p>An Extra Primary Key gives you a second way to <em>address the same record</em>. Lists and Projections create <em>additional records</em> underneath it. Everything else follows from that.</p></div><h2 id="quick-chooser" tabindex="-1">Quick chooser <a class="header-anchor" href="#quick-chooser" aria-label="Permalink to &quot;Quick chooser&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You have…</th><th>Use</th><th>Where</th></tr></thead><tbody><tr><td>One record the system stores in two tables, under two different ids</td><td><strong>Extra Primary Key</strong></td><td>Data Model → <strong>Extra Primary Keys</strong> tab</td></tr><tr><td>A child collection the common model already declares (an Order&#39;s Lines, an Item&#39;s Prices)</td><td><strong>Built-In</strong> list</td><td>Lists tab → List Type = <strong>Built-In</strong></td></tr><tr><td>A child collection the common model <em>doesn&#39;t</em> declare, and nothing else points at the children</td><td><strong>Custom List</strong></td><td>Lists tab → List Type = <strong>Custom List</strong></td></tr><tr><td>A second level of one relationship that other records need to <em>reference</em> — and that some systems treat as the whole record</td><td><strong>Projection</strong></td><td>Lists tab → List Type = <strong>Projection</strong></td></tr></tbody></table><h2 id="extra-primary-keys" tabindex="-1">Extra Primary Keys — one record, two identifiers <a class="header-anchor" href="#extra-primary-keys" aria-label="Permalink to &quot;Extra Primary Keys — one record, two identifiers {#extra-primary-keys}&quot;">​</a></h2><p>An Extra Primary Key is an <strong>additional identifier on the same record, in the same system.</strong> The record does not multiply. You are telling Central &quot;this system also knows this record as <em>X</em>&quot;, so that data arriving under either identifier lands on the same entity.</p><p>The classic case is a system that replicates one thing into two tables — Locations that also appear in a Departments table, each with its own id. One Central record, two ways in.</p><p>Reach for one when <strong>all</strong> of these hold:</p><ul><li>It is genuinely the same business record — same name, same attributes, same lifecycle.</li><li>The second identifier comes from the <strong>same</strong> source system.</li><li>Nothing needs to reference the two identities <em>differently</em>. They are interchangeable.</li></ul><p>If any of those breaks — especially the last — you want a Projection, not an extra key.</p><div class="warning custom-block"><p class="custom-block-title">Extra keys don&#39;t split a record</p><p>If you find yourself wanting different attribute values, a different lifecycle, or different downstream routing for the &quot;second identity&quot;, you are describing two records. Extra keys cannot express that, and forcing them to will produce one record whose values are whichever side wrote last.</p></div><p>See <a href="./build-data-models.html#adding-extra-primary-keys">Data Models → Adding Extra Primary Keys</a> for the mechanics. Extra keys also surface on referencing entities as <a href="./reference-related-data.html">Related Data</a>.</p><h2 id="lists-built-in-vs-custom" tabindex="-1">Lists — Built-In vs Custom <a class="header-anchor" href="#lists-built-in-vs-custom" aria-label="Permalink to &quot;Lists — Built-In vs Custom {#lists-built-in-vs-custom}&quot;">​</a></h2><p>Both kinds of list hold child records. The only difference is <strong>whether the common model already declares the relationship.</strong></p><table tabindex="0"><thead><tr><th></th><th>Built-In</th><th>Custom List</th></tr></thead><tbody><tr><td><strong>Declared by</strong></td><td>The platform — Lines, Prices, Addresses, and so on</td><td>You — you type the list&#39;s name</td></tr><tr><td><strong>Chosen via</strong></td><td>The <strong>List Property</strong> dropdown, filtered to your entity type</td><td>A free-text <strong>List Name</strong> field</td></tr><tr><td><strong>Child entity</strong></td><td>The declared item entity type</td><td><code>ChildCustomEntity</code>, shaped by a child Data Model</td></tr><tr><td><strong>Child sub-type</strong></td><td>Optional</td><td><strong>Required</strong> — the platform errors without one</td></tr></tbody></table><p><strong>Prefer Built-In whenever one fits.</strong> A declared list property is understood by the rest of the platform out of the box: the common model documents it, references to it resolve conventionally, and consumers know what an Order&#39;s <code>Lines</code> are without being told. A Custom List is a name you invented, so everything downstream has to be told about it.</p><p>Reach for a <strong>Custom List</strong> when the relationship you need genuinely isn&#39;t declared and you don&#39;t want to change the base entity to add it — professional certifications on a Contact, inspections on a Location, compliance records on a Product. You get a real, keyed child collection without a model change rippling through every consumer of that entity.</p><div class="info custom-block"><p class="custom-block-title">A Custom List name can&#39;t shadow a built-in one</p><p>If you type a name that matches a declared list property, Central rejects it and points you at the <strong>List Property</strong> dropdown. This is deliberate — two different mechanisms answering to the same name is the kind of ambiguity that only shows up in production.</p></div><p><a href="./custom-lists.html">Custom Lists</a> covers the full setup; both kinds are populated the same way, via <a href="./looping-lists.html">Looping Lists</a>.</p><h2 id="projections" tabindex="-1">Projections — a second level that other records reference <a class="header-anchor" href="#projections" aria-label="Permalink to &quot;Projections — a second level that other records reference {#projections}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Preview</p><p>Projections are in <strong>Preview</strong> alongside Custom Lists and are rolling out across environments. Your Central environment may not run them yet.</p></div><p>A <strong>Projection</strong> is a child list whose children represent <strong>a second level of one relationship</strong> — a location under a customer, a licence under an account, a property under a company. Mechanically it is a Custom List whose child Data Model carries the reserved sub-type <code>ParentProjection</code>. What makes it its own List Type is what the platform does with it afterwards.</p><p>The thing that makes a Projection necessary — and a Custom List insufficient — is this:</p><blockquote><p><strong>Different systems disagree about which level is &quot;the record&quot;.</strong></p></blockquote><p>One system stores the account and its locations as two things. A second system&#39;s customers <em>are</em> the locations; it has no account at all. A third only has the account. All three are integrated against the same Central data, and a single order has to route correctly to all three.</p><p>That is what a Projection expresses. The base record and its projections are two levels of one relationship, and Central works out <strong>per system</strong> which level that system actually models, from the keys the projections carry. You do not configure that mapping; it is inferred from the data.</p><h3 id="setting-one-up" tabindex="-1">Setting one up <a class="header-anchor" href="#setting-one-up" aria-label="Permalink to &quot;Setting one up&quot;">​</a></h3><ol><li>On the parent Data Model, open the <strong>Lists</strong> tab and set <strong>List Type</strong> to <strong>Projection</strong>.</li><li>Enter a <strong>List Name</strong> — <code>Locations</code>, <code>Licenses</code>, <code>Properties</code>. This is how the list is addressed on the entity.</li><li>Choose the child <strong>Data Model</strong>. The picker offers only <code>ChildCustomEntity</code> models carrying the <code>ParentProjection</code> sub-type; <strong>➕ Add New Data Model…</strong> creates one with that sub-type already set.</li><li>On that child Data Model, set the <strong>Projection Key</strong> — the single property that identifies a projection within its parent. The picker appears at the top of the Data Model modal once the sub-type is <code>ParentProjection</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">The projection key does not have to be globally unique</p><p>It only has to be unique <strong>within one parent</strong>. Two customers can both have a location called <em>Main Warehouse</em>; a reference always names the parent as well, so the search space is only ever that one parent&#39;s children. This is why a projection key can be a human label rather than an id.</p></div><div class="warning custom-block"><p class="custom-block-title"><code>ParentProjection</code> is reserved</p><p>You cannot type it as a custom Sub Type on a Data Model. Create the list with <strong>List Type = Projection</strong> and let Central seed the sub-type — that path also wires the projection key and the child&#39;s key maps for you.</p></div><h3 id="referencing-a-projection" tabindex="-1">Referencing a projection <a class="header-anchor" href="#referencing-a-projection" aria-label="Permalink to &quot;Referencing a projection&quot;">​</a></h3><p>A record that points at a projection — an order pointing at the customer&#39;s location — needs two values to say what it means: <strong>which base record</strong>, and <strong>which projection within it</strong>. Central carries both on a single reference, which the map editor labels <strong>[Projection Reference]</strong> with <code>base</code> and <code>projection</code> badges on the two source columns.</p><p>It is an ordinary reference in every other respect. It resolves like one, indexes like one, and appears in the data model like one.</p><div class="info custom-block"><p class="custom-block-title">Authoring today</p><p>The map editor <strong>displays</strong> a projection reference but does not yet create one — the flag that marks the projection column is set through <a href="./datahub-code-view.html">Code View</a>. A visual-editor control is planned.</p></div><h2 id="custom-list-or-projection" tabindex="-1">Custom List or Projection? <a class="header-anchor" href="#custom-list-or-projection" aria-label="Permalink to &quot;Custom List or Projection?&quot;">​</a></h2><p>This is the choice most likely to go wrong, because a Projection <em>is</em> a Custom List underneath. The test is not what the children look like — it is what points at them.</p><table tabindex="0"><thead><tr><th>Ask</th><th>Custom List</th><th>Projection</th></tr></thead><tbody><tr><td>Does anything outside the parent <strong>reference</strong> an individual child?</td><td>No</td><td><strong>Yes</strong> — that is the whole point</td></tr><tr><td>Do connected systems disagree about whether the child or the parent is &quot;the record&quot;?</td><td>No</td><td><strong>Yes</strong></td></tr><tr><td>Is the child a real, independent thing in its own right?</td><td>Yes — a certification, an inspection</td><td>Not really — it is a re-slice of its parent</td></tr><tr><td>Does a child ever need to route a <em>different</em> record somewhere?</td><td>No</td><td><strong>Yes</strong></td></tr></tbody></table><p>A Contact&#39;s certifications are a Custom List: they travel with the contact and nothing addresses one on its own. A Customer&#39;s licences are a Projection: an order names one, and one downstream system thinks the licence <em>is</em> the customer.</p><div class="tip custom-block"><p class="custom-block-title">When in doubt, start with the Custom List</p><p>It is the smaller commitment, and a list can be re-modelled as a Projection later. Going the other way is harder, because by then other records are referencing the children.</p></div><h2 id="worked-comparison" tabindex="-1">Worked comparison <a class="header-anchor" href="#worked-comparison" aria-label="Permalink to &quot;Worked comparison&quot;">​</a></h2><p>One scenario — <em>a customer that operates from several sales locations</em> — modeled four ways, and what each gets you.</p><table tabindex="0"><thead><tr><th>Model</th><th>What Central holds</th><th>An order can say…</th><th>Works when</th></tr></thead><tbody><tr><td><strong>Extra Primary Key</strong> on the Customer</td><td>One customer, addressable by two ids</td><td>&quot;customer 1001&quot; (either id)</td><td>The two ids are the same customer and nothing distinguishes them — <strong>not this scenario</strong></td></tr><tr><td><strong>Built-In list</strong></td><td>Not available — the common model does not declare sales locations on a Company</td><td>—</td><td>—</td></tr><tr><td><strong>Custom List</strong> <code>Locations</code></td><td>One customer + N location children</td><td>&quot;customer 1001&quot; only</td><td>Locations are reference data you carry along, and nothing routes by them</td></tr><tr><td><strong>Projection</strong> <code>Locations</code></td><td>One customer + N location children, each keyed per system</td><td>&quot;customer 1001, location <em>Loma Vista Sales</em>&quot;</td><td>A system models locations as its customers, or an order must route per location</td></tr></tbody></table><p>The first three all collapse the order onto the customer. Only the Projection preserves which location the order was for — and only the Projection lets one system receive the location while another receives the account, from the same single reference.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./build-data-models.html">Data Models</a> — Properties, Extra Primary Keys, List Properties, Sub-Types</li><li><a href="./custom-lists.html">Custom Lists</a> — Setting up a free-form child collection</li><li><a href="./looping-lists.html">Looping Lists</a> — Populating any list: Loop All, Group by Field, Split by Separator</li><li><a href="./reference-related-data.html">Related Data</a> — Carrying a referenced entity&#39;s values onto the referencing record</li><li><a href="./reference-common-model.html">Common Model Definitions</a> — What the platform already declares</li></ul>',47)])])}const p=e(a,[["render",n]]);export{u as __pageData,p as default};
